def maskPII(S: str) -> str:
    if '@' in S:
        name, rest = S.split('@')
        domain = rest.lower()
        first_char = name[0].lower()
        last_char = name[-1].lower()
        return f"{first_char}*****{last_char}@{domain}"
    else:
        digits = [c for c in S if c.isdigit()]
        last_four = ''.join(digits[-4:])
        if len(digits) == 10:
            return f"***-***-{last_four}"
        else:
            country_code_len = len(digits) - 10
            asterisks = '*' * country_code_len
            return f"+{asterisks}-***-***-{last_four}"
